from collections.abc import Sequence

import sqlalchemy as sa

from alembic import op

# revision identifiers, used by Alembic.
revision: str = "5"
down_revision: str | Sequence[str] | None = "4"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

TABLES = ["item", "batch", "todo", "task"]


def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    for table in TABLES:
        # Drop the serial sequence default first — it cannot be cast to uuid.
        op.execute(f"ALTER TABLE {table} ALTER COLUMN id DROP DEFAULT")
        # PostgreSQL has no implicit int -> uuid cast; convert via text.
        op.alter_column(
            table,
            "id",
            existing_type=sa.INTEGER(),
            type_=sa.Uuid(),
            existing_nullable=False,
            postgresql_using="id::text::uuid",
        )
        op.execute(f"DROP SEQUENCE IF EXISTS {table}_id_seq")
    # ### end Alembic commands ###


def downgrade() -> None:
    """Downgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    # uuid -> int is lossy; only valid on empty tables (fails loudly otherwise).
    for table in reversed(TABLES):
        op.alter_column(
            table,
            "id",
            existing_type=sa.Uuid(),
            type_=sa.INTEGER(),
            existing_nullable=False,
            postgresql_using="id::text::integer",
        )
        op.execute(f"CREATE SEQUENCE IF NOT EXISTS {table}_id_seq")
        op.execute(
            f"ALTER TABLE {table} ALTER COLUMN id SET DEFAULT nextval('{table}_id_seq'::regclass)"
        )
    # ### end Alembic commands ###
